SELECT COUNT(*) AS total_facturas_vencidas
FROM invoices
WHERE status = 'overdue';

SELECT COUNT(*) AS total_customers
FROM customers
WHERE country = 'Colombia';

SELECT SUM(amount) AS total_amount
FROM invoices
WHERE currency = 'USD';

SELECT COUNT(*) AS total_pending_invoices
FROM invoices
WHERE status = 'pending';

SELECT COUNT(*) AS total_facturas
FROM invoices
WHERE DATE_TRUNC('month', issued_date) = '2026-07-01'::date;

SELECT COUNT(*) AS total_facturas
FROM invoices
WHERE due_date BETWEEN '2026-10-01' AND '2026-10-31';

SELECT COUNT(*) AS total_customers_registered
FROM customers
WHERE EXTRACT(YEAR FROM registration_date) = 2025;

SELECT payment_method, COUNT(*) AS payment_count
FROM payments
GROUP BY payment_method;

SELECT AVG(p.paid_at::date - i.issued_date) AS avg_days_between_issue_and_payment
FROM invoices i
JOIN payments p ON p.invoice_id = i.invoice_id;

SELECT currency, AVG(amount) AS average_amount
FROM invoices
GROUP BY currency;

SELECT COUNT(c.customer_id) AS customers_without_payments
FROM customers c
WHERE c.customer_id NOT IN (SELECT i.customer_id FROM invoices i JOIN payments p ON p.invoice_id = i.invoice_id);

SELECT COUNT(*) AS customers_without_invoices
FROM customers
WHERE customer_id NOT IN (SELECT customer_id FROM invoices);

SELECT DISTINCT payment_method
FROM payments
ORDER BY payment_method;

